//! Every generated kernel of `pga2d`, checked against the dense oracle.
#![allow(clippy::pedantic, clippy::too_many_lines)]

mod common;
use common::{Oracle, Rng, assert_close, random};
use gax::pga2d::*;
use gax::{Extensor, Unit};
use gax_gen::table::{BinOp, UnOp};

const SPEC: &str = include_str!("../specs/pga2d.gax");

fn bin<A, B, R>(o: &Oracle, rng: &mut Rng, op: BinOp, f: impl Fn(A, B) -> R)
where
    A: Extensor<Slots = (), Coef = f64>,
    B: Extensor<Slots = (), Coef = f64>,
    R: Extensor<Slots = (), Coef = f64>,
{
    for _ in 0..8 {
        let (a, b): (A, B) = (random(rng), random(rng));
        let want = o.binop(op, &o.dense(&a), &o.dense(&b));
        assert_close(
            &o.dense(&f(a, b)),
            &want,
            &format!(
                "{op:?} {} {}",
                std::any::type_name::<A>(),
                std::any::type_name::<B>()
            ),
        );
    }
}

fn un<A, R>(o: &Oracle, rng: &mut Rng, op: UnOp, f: impl Fn(A) -> R)
where
    A: Extensor<Slots = (), Coef = f64>,
    R: Extensor<Slots = (), Coef = f64>,
{
    for _ in 0..8 {
        let a: A = random(rng);
        assert_close(
            &o.dense(&f(a)),
            &o.unop(op, &o.dense(&a)),
            &format!("{op:?} {}", std::any::type_name::<A>()),
        );
    }
}

/// `v x ~v` against the oracle; with `unit`, `v` is first scaled so that `<v ~v>_0 = 1`
/// (sufficient for the algebras whose versors have scalar norms).
fn sandwich<V, X, R>(o: &Oracle, rng: &mut Rng, unit: bool, f: impl Fn(V, X) -> R)
where
    V: Extensor<Slots = (), Coef = f64> + gax::Gp<f64, Output = V>,
    X: Extensor<Slots = (), Coef = f64>,
    R: Extensor<Slots = (), Coef = f64>,
{
    for _ in 0..8 {
        let (mut v, x): (V, X) = (random(rng), random(rng));
        let norm = |v: &V| {
            let d = o.dense(v);
            o.binop(BinOp::Gp, &d, &o.unop(UnOp::Reverse, &d))
        };
        if unit {
            let n = norm(&v);
            if n[0] <= 1e-3 || n[1..].iter().any(|c| c.abs() > 1e-12) {
                continue;
            }
            v = v.gp(1.0 / n[0].sqrt());
        }
        let (dv, dx) = (o.dense(&v), o.dense(&x));
        let want = o.binop(
            BinOp::Gp,
            &o.binop(BinOp::Gp, &dv, &dx),
            &o.unop(UnOp::Reverse, &dv),
        );
        assert_close(
            &o.dense(&f(v, x)),
            &want,
            &format!(
                "sandwich {} {}",
                std::any::type_name::<V>(),
                std::any::type_name::<X>()
            ),
        );
    }
}

